import{_ as o,a0 as m,w as r,s,ao as l,I as a,x as e,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux Uptime 命令，让你知道你的系统运行了多久 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Uptime 命令，让你知道你的系统运行了多久 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Uptime 命令，让你知道你的系统运行了多久 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Uptime 命令，让你知道你的系统运行了多久 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Linux Uptime Command – Find How Long Your System Been Running","title":"Linux Uptime 命令，让你知道你的系统运行了多久","tag":"201312","desc":""},"relativePath":"201312/Linux Uptime Command – Find How Long Your System Been Running.md","filePath":"[post].md"}'),u={name:"201312/Linux Uptime Command – Find How Long Your System Been Running.md"};function d(x,t,g,h,L,T){const n=m("Link");return r(),s("div",null,[t[11]||(t[11]=l(`<h1 id="linux-uptime-命令-让你知道你的系统运行了多久" tabindex="-1">Linux Uptime 命令，让你知道你的系统运行了多久 <a class="header-anchor" href="#linux-uptime-命令-让你知道你的系统运行了多久" aria-label="Permalink to “Linux Uptime 命令，让你知道你的系统运行了多久”">​</a></h1><p><img src="http://linoxide.com/wp-content/uploads/2013/11/linux-uptime-command.png" alt=""></p><p>对于一些人来说系统运行了多久是无关紧要的，但是对于服务器管理员来说，这是相当重要的信息。服务器在运行重要应用的时候，必须尽量保证长时间的稳定运行，有时候甚至要求零宕机。那么我们怎么才能知道服务器运行了多久呢？</p><p>在Linux 下，我们可以使用uptime 命令，而且此命令不必使用root 权限。uptime 命令在系统中已经默认安装了。</p><p>语法如下：</p><pre><code>$ uptime
</code></pre><p>你会在屏幕上看到如下显示：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime.png" alt=""></p><p>这些信息保存在/proc/uptime 文件中，虽然是以文本方式保存，但是这些数据却不能直接显示，这就需要我们使用uptime 命令来翻译它。</p><p>以下是如何解读uptime 提供的信息：</p><h3 id="系统时间" tabindex="-1">系统时间 <a class="header-anchor" href="#系统时间" aria-label="Permalink to “系统时间”">​</a></h3><p>在图1中，左起第一条信息是14:04:39，这就是当前系统时间，以24小时格式输出。</p><h3 id="系统运行时间" tabindex="-1">系统运行时间 <a class="header-anchor" href="#系统运行时间" aria-label="Permalink to “系统运行时间”">​</a></h3><p>第二条信息<strong>Up 1004 days, 12:20</strong>，这是显示你的系统运行时间。图1 显示你的系统已经运行了1004天12小时20分钟，如果你的系统没有运行超过24小时，这里将只会显示小时分钟或者只显示分钟。注意图2、图3的信息，当系统重启后将会清零。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime_minutes.png" alt=""></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime_hours1.png" alt=""></p><h3 id="已登录用户的数量" tabindex="-1">已登录用户的数量 <a class="header-anchor" href="#已登录用户的数量" aria-label="Permalink to “已登录用户的数量”">​</a></h3><p>第三部分的信息是显示已登陆用户的数量。在图1中，显示的是<strong>1 user</strong> ，即当前登录用户数量。当多个用户在同时登陆系统时，uptime 命令将告诉你用户的数量。</p><h3 id="平均负载量" tabindex="-1">平均负载量 <a class="header-anchor" href="#平均负载量" aria-label="Permalink to “平均负载量”">​</a></h3><p>最后一个信息是系统的平均负载量。回到图1，你看到这样带两位小数的数字<strong>0.25, 0.25, 0.19</strong>可以换算成百分比，即0.25和0.19分别代表着25%和19%。0.25, 0.25, 0.19分别代表着过去1分钟、5分钟、15分钟系统的平均负载量。负载量越低意味着你的系统性能越好。</p><p>这就是<strong>uptime</strong> 命令的日常使用指导，如果想获取更详细的信息，请通过输入<strong>man uptime</strong> 进入uptime 命令的manual 页面来查看。</p><p>你的机器已经运行多久了？贴出你的uptime给大家看看吧。</p><hr>`,23)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(n,{href:"http://linoxide.com/linux-command/linux-uptime-command/"},{default:p(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-uptime-command/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),i(n,{href:"https://github.com/NearTan"},{default:p(()=>[...t[2]||(t[2]=[e("NearTan",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),i(n,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const c=o(u,[["render",d]]);export{_ as __pageData,c as default};
